    subscribeToGameEvents: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                gameId: components["parameters"]["gameId"];
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Successful response. */
            200: {
                headers: {
                    /** @description no-cache, no-transform */
                    "Cache-Control"?: string;
                    /** @description no */
                    "X-Accel-Buffering"?: string;
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example : connected
                     *
                     *     data: {"type":"roster"}
                     */
                    "text/event-stream": string;
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            404: components["responses"]["NotFound"];
            /** @description Stream capacity reached; rejected before SSE headers with code ERR01. */
            429: {
                headers: {
                    /** @description Seconds before retrying; 15 by default. */
                    "Retry-After"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            500: components["responses"]["ServerError"];
            /** @description The event service is shutting down or the database is busy; code ERR02 or ERR88. */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
